import test from 'node:test';
import assert from 'node:assert/strict';
import {applyNodeEdit,applyRelationEdit} from 'fm4/fm/core';
import {FreshmindPanel,captureDocument,installDocument} from 'fm4/fm/browser';
import {parseDocument,serializeDocument,documentToRecord} from 'fm4/fm/io';
import {createSearchCorpus} from 'fm4/ir';
import {SearchWorkerClient,SearchSession,SearchCancelledError} from 'fm4/ir/browser';
import {trainLda} from 'fm4/ir/topics';

// Hand-authored independent semantic oracle. IDs, endpoints and unusual values
// are literal expectations, not generated by the serializer under test.
const source={format:'freshmind',version:1,title:'Assurance α',data:{purpose:'preserve'},extensions:{app:{version:1}},
  nodes:[{id:'a',label:'Alpha',type:'default',weight:2,annotation:{format:'html',text:'<p>literal</p>'},url:'https://example.invalid/retained',data:{nested:[1,true,null]},extensions:{app:{x:'α'}}},
    {id:'b',label:'Beta',type:'default',weight:1},{id:'hidden',label:'Hidden',type:'default',weight:1}],
  edges:[{id:'ab',from:'a',to:'b',label:'uses',type:'default',weight:0,length:60,data:{evidence:'one'}},
    {id:'parallel',from:'a',to:'b',label:'also uses',type:'default',weight:3,length:70},
    {id:'loop',from:'b',to:'b',label:'self',type:'default',weight:1,length:80}]};
function fixture(){const doc=parseDocument(JSON.stringify(source));let i=0;for(const n of doc.graph.getNodes()){n.x=i*60;n.y=i*30;i++;}return doc;}
function semantic(document){
  const record=documentToRecord(document);delete record.types;delete record.view;
  for(const n of record.nodes){delete n.position;delete n.fixed;delete n.visual;if(!Object.keys(n.data??{}).length)delete n.data;if(!Object.keys(n.extensions??{}).length)delete n.extensions;if(!n.url)delete n.url;if(!n.annotation?.text)delete n.annotation;}
  for(const e of record.edges){delete e.visual;if(!Object.keys(e.data??{}).length)delete e.data;if(!Object.keys(e.extensions??{}).length)delete e.extensions;}
  return record;
}
test('ASSURE-01 hidden/parallel/loop semantic records survive composed views and native round trips',async t=>{
  const document=fixture(),panel=new FreshmindPanel(undefined,{autoStart:false,animateLocality:false});t.after(()=>panel.destroy());
  assert.deepEqual(semantic(document),source);
  await installDocument(panel,document);await panel.setLocale(panel.findNode('a'),0);
  assert.ok(panel.getGES().nodeCount()<3);
  panel.getGES().addAll();panel.getRfc().setFocus(panel.findNode('a'));panel.tgLayout.setAdaptiveDampingEnabled(false);panel.setZoom(1.7);panel.setRotation(.4);panel.setCanvasPan(20,-10);const positions=[...document.graph.getNodes()].map(n=>[n.x,n.y]);panel.tgLayout.tick();assert.notDeepEqual([...document.graph.getNodes()].map(n=>[n.x,n.y]),positions);
  const saved=parseDocument(serializeDocument(captureDocument(panel,document)));
  assert.deepEqual(semantic(saved),source);
});
test('ASSURE-02 invalid late fields preserve every accepted record and adjacency',()=>{
  const doc=fixture(),a=doc.graph.findNode('a'),edge=[...doc.graph.getEdges()].find(e=>e.getID()==='ab');
  const before=documentToRecord(doc),incidence=()=>[...doc.graph.getNodes()].map(n=>[n.getID(),[...n.getEdges()].map(e=>e.getID())]);const adjacent=incidence();
  for(const weight of [NaN,Infinity,-1]){
    assert.throws(()=>applyNodeEdit(a,{label:'must not stick',type:'default',shape:null,annotation:{format:'text',text:'changed'},weight}));
    assert.deepEqual(documentToRecord(doc),before);assert.deepEqual(incidence(),adjacent);
  }
  for(const draft of [{weight:NaN},{length:-1},{to:'missing'},{data:{invalid:Infinity}}]){
    assert.throws(()=>applyRelationEdit(edge,{label:'must not stick',type:'default',curve:null,...draft},{graph:doc.graph}));
    assert.deepEqual(documentToRecord(doc),before);assert.deepEqual(incidence(),adjacent);
  }
});
function controlled(){
  const workers=[];return {workers,factory:()=>{const w={onmessage:null,onerror:null,terminated:0,postMessage(job){this.job=job;},terminate(){this.terminated++;}};workers.push(w);return w;}};
}
const corpus=createSearchCorpus([{id:'a',label:'graph layout',type:'note',hint:'',tags:[]},{id:'b',label:'topic search',type:'note',hint:'',tags:[]}]);
test('ASSURE-03 already-queued callbacks cannot report progress or finish newer jobs',async()=>{
  const transport=controlled(),client=new SearchWorkerClient(transport.factory),progress=[];
  const old=client.run({kind:'index',corpus},p=>progress.push(p)),rejected=assert.rejects(old,SearchCancelledError);
  const callback=transport.workers[0].onmessage,error=transport.workers[0].onerror;
  const newer=client.run({kind:'index',corpus});await rejected;
  callback({data:{kind:'progress',progress:{iteration:999}}});
  callback({data:{kind:'indexed',key:'stale',documents:99}});error({message:'stale error'});
  assert.deepEqual(progress,[]);assert.equal(client.busy,true);assert.equal(transport.workers[1].terminated,0);
  transport.workers[1].onmessage({data:{kind:'indexed',key:corpus.key,documents:2}});
  assert.deepEqual(await newer,{kind:'indexed',key:corpus.key,documents:2});
  assert.deepEqual(transport.workers.map(w=>w.terminated),[1,1]);client.dispose();
  await assert.rejects(client.run({kind:'index',corpus}),/disposed/);
});
test('ASSURE-04 out-of-order model reads cannot replace the latest accepted session model',async()=>{
  const session=new SearchSession(),oldModel=trainLda(corpus,{topics:2,iterations:3,seed:7}),newModel=trainLda(corpus,{topics:2,iterations:3,seed:19});
  let finish;const old=session.loadModel(corpus,()=>new Promise(resolve=>finish=resolve));const rejection=assert.rejects(old,SearchCancelledError);
  await session.loadModel(corpus,async()=>newModel);finish(oldModel);await rejection;
  assert.deepEqual(session.exportModel(corpus),newModel);session.dispose();
});
